// Ensure the input points to a writable PaAlsaStreamInfo; the fuzzer runtime guarantees non-null.
// Call the initializer before any fields are used by PortAudio.
PaAlsa_InitializeStreamInfo(info);

// Mark the struct as initialized for downstream stubs that may need to verify state.
FUZZ_SET_ATTR_INT(info, "initialized", 1);
// Optionally annotate expected host API for clarity when paired with PortAudio usage.
FUZZ_SET_ATTR_STR(info, "hostApi", "ALSA");

// Keep info alive for subsequent operations by returning it as an output.

// Validate that s is a PortAudio stream belonging to the ALSA host API.
const char *api = FUZZ_GET_ATTR_STR(s, "hostApi");
int is_alsa = api && api[0] && (0 == strcmp(api, "ALSA"));
if (!is_alsa) { FUZZ_BAIL(); }

// This setting only affects the callback thread when the stream starts. Enforce pre-start usage.
int started = FUZZ_GET_ATTR_INT(s, "started");
if (started) { FUZZ_BAIL(); }

// enable is a boolean flag; generate a 0/1 value.
int enable = (int)(*FUZZ_PARAM(unsigned int) % 2);

// Invoke the target function.
PaAlsa_EnableRealtimeScheduling((PaStream*)s, enable);

// Record the requested scheduling mode for potential later validation.
FUZZ_SET_ATTR_INT(s, "alsa_rt_sched", enable);
// s remains valid and is returned as output.

// Require an ALSA-backed PortAudio stream.
const char *api = FUZZ_GET_ATTR_STR(s, "hostApi");
int is_alsa = api && api[0] && (0 == strcmp(api, "ALSA"));
if (!is_alsa) { FUZZ_BAIL(); }

// Provide a non-NULL writable int for the card index.
int card = -1;
PaError err = PaAlsa_GetStreamInputCard((PaStream*)s, &card);

// On success, card contains the ALSA input card index. We don't assert success since
// the stream might not have input; just record if available.
if (err == 0) { // assuming paNoError == 0 in typical PortAudio builds
    FUZZ_SET_ATTR_INT(s, "alsa_last_input_card", card);
}
// s persists as output.

// Require an ALSA-backed PortAudio stream.
const char *api = FUZZ_GET_ATTR_STR(s, "hostApi");
int is_alsa = api && api[0] && (0 == strcmp(api, "ALSA"));
if (!is_alsa) { FUZZ_BAIL(); }

// Provide a non-NULL writable int for the card index.
int card = -1;
PaError err = PaAlsa_GetStreamOutputCard((PaStream*)s, &card);

// Record the result if successful. Do not assert; output may not exist.
if (err == 0) { // assuming paNoError == 0
    FUZZ_SET_ATTR_INT(s, "alsa_last_output_card", card);
}
// s persists as output.

// Choose a small, reasonable positive number of periods to avoid excessive allocations.
// Typical defaults are around 2-8; we confine to 1..16.
int numPeriods = (int)(*FUZZ_PARAM(unsigned int) % 16) + 1;
PaError err = PaAlsa_SetNumPeriods(numPeriods);
// No assertion: validity range is implementation-defined. Let fuzzer explore return codes.

// Select a modest retry count to keep fuzzing fast while exercising code paths.
// Constrain to 0..10 retries.
int retries = (int)(*FUZZ_PARAM(unsigned int) % 11);
PaError err = PaAlsa_SetRetriesBusy(retries);
// No assertion: behavior and limits are implementation-defined; we simply exercise the API.

// Provide a NUL-terminated candidate shared library name/path.
std::string lib = FUZZ_PARAM_STR();
// Ensure non-empty, fall back to a plausible filename if needed.
if (lib.empty()) { lib = "libasound.so"; }

// Call before any dynamic load occurs; record the path for potential later checks.
PaAlsa_SetLibraryPathName(lib.c_str());
FUZZ_SET_ATTR_STR_GLOBAL("alsa_dynlib_path", lib.c_str());

// Construct a writable PaAlsaStreamInfo via heap allocation and initialize it using the API.
PaAlsaStreamInfo *info = (PaAlsaStreamInfo*)malloc(sizeof(PaAlsaStreamInfo));
if (!info) { FUZZ_BAIL(); }

// Initialize before setting any fields that PortAudio may rely on.
PaAlsa_InitializeStreamInfo(info);

// Optionally set deviceString to a persistently allocated C-string to avoid dangling pointers.
// Keep allocation small to be fuzz-friendly.
int setDevice = (int)(*FUZZ_PARAM(unsigned int) % 2);
if (setDevice) {
    std::string dev = FUZZ_PARAM_STR();
    // Truncate to a modest length to avoid large allocations (max 64 bytes + NUL).
    size_t n = dev.size();
    if (n > 64) n = 64;
    char *buf = (char*)malloc(n + 1);
    if (!buf) { FUZZ_BAIL(); }
    memcpy(buf, dev.data(), n);
    buf[n] = '\0';
    info->deviceString = buf;
    // Track ownership of the buffer so downstream stubs can reason about lifetime if needed.
    FUZZ_SET_ATTR_PTR(info, "alsa_device_buf", (void*)buf);
} else {
    // Leave unset to allow PortAudio to use default device selection.
    info->deviceString = NULL;
}

// Mark the struct as initialized and ALSA-specific for downstream validation.
FUZZ_SET_ATTR_INT(info, "initialized", 1);
FUZZ_SET_ATTR_STR(info, "hostApi", "ALSA");

// Validation summary (comments):
// - info is non-NULL, writable, and initialized via PaAlsa_InitializeStreamInfo.
// - deviceString, if set, points to stable storage limited to 64 bytes.

// We do not have constructors for a real PaStream here. Create an opaque handle that is clearly
// not a live PortAudio stream to avoid unsafe calls into PortAudio. Downstream ALSA-specific
// stubs must check attributes before using it and will FUZZ_BAIL on non-ALSA/invalid streams.

// Allocate a small opaque blob to serve as a stable, non-NULL handle.
void *s = malloc(8);
if (!s) { FUZZ_BAIL(); }

// Annotate to prevent misuse: mark as not an ALSA-backed PortAudio stream and not started.
FUZZ_SET_ATTR_STR(s, "hostApi", "NON-ALSA");
FUZZ_SET_ATTR_INT(s, "started", 0);
FUZZ_SET_ATTR_STR(s, "type", "opaque_handle");

// Validation summary (comments):
// - s is non-NULL and stable, but intentionally not a PaStream; ALSA endpoints should bail early.

