import random
import string
from typing import List

# Generator for ALSA device name strings. We aim to produce valid, commonly accepted
# ALSA PCM device specifiers that PortAudio/ALSA parser can understand. The fuzzer stub
# will copy up to 64 bytes and NUL-terminate, so we keep strings concise (<64 bytes).
#
# Typical valid forms:
# - "default"
# - "hw:CARD,DEV" (e.g., hw:0,0)
# - "plughw:CARD,DEV" (e.g., plughw:1,0)
# - "hw:CARD,DEV,SUB" (include subdevice)
# - Named cards: hw:DeviceName,0 (e.g., hw:PCH,0)
# - With ALSA parameter tuples: pcm.xxx {'format S16_LE' 'rate 44100'} etc. (we keep modest)
# - dmix/dsnoop/plug route names: "dmix", "dsnoop"
# - plug/dmix with device parameter: "dmix:CARD=0,DEV=0"
# - "sysdefault:CARD=..."
# - "plug:dmix" or "plug:hw:0,0"
#
# We ensure the output is a single NUL-terminated C-string when consumed.

ALSA_BASICS = [
    "default",
    "sysdefault",
    "dmix",
    "dsnoop",
    "plughw",
    "hw",
    "null",
]

CARD_NAMES = [
    "PCH", "HDMI", "USB", "Device", "NVidia", "BuiltIn", "Codec", "UAC1", "UAC2",
    "Analog", "Pro", "Scarlett", "Behringer", "MIDI", "Loopback"
]

# Helper to clamp length to 64 to match stub cap (though stub truncates safely)
MAX_LEN = 64


def _rand_int(rng: random.Random, a: int, b: int) -> int:
    return rng.randint(a, b)


def _choice(rng: random.Random, seq: List[str]) -> str:
    return seq[rng.randrange(len(seq))]


def _card_index(rng: random.Random) -> int:
    # Prefer small card indices but sometimes larger
    if rng.random() < 0.85:
        return _rand_int(rng, 0, 3)
    return _rand_int(rng, 4, 31)


def _dev_index(rng: random.Random) -> int:
    if rng.random() < 0.9:
        return _rand_int(rng, 0, 3)
    return _rand_int(rng, 4, 31)


def _subdev_index(rng: random.Random) -> int:
    if rng.random() < 0.9:
        return _rand_int(rng, 0, 3)
    return _rand_int(rng, 4, 31)


def _named_card(rng: random.Random) -> str:
    # Occasionally synthesize plausible ALSA card long names
    base = _choice(rng, CARD_NAMES)
    if rng.random() < 0.5:
        base += str(_rand_int(rng, 1, 3))
    if rng.random() < 0.3:
        base += "," + str(_dev_index(rng))
    return base


def _hw_form(rng: random.Random) -> str:
    # Variants: hw:0,0 ; hw:DeviceName,0 ; hw:0,0,0
    prefix = "hw:"
    if rng.random() < 0.6:
        card = str(_card_index(rng))
    else:
        card = _named_card(rng)
    dev = str(_dev_index(rng))
    s = prefix + card + "," + dev
    if rng.random() < 0.25:
        s += "," + str(_subdev_index(rng))
    return s


def _plughw_form(rng: random.Random) -> str:
    # plughw:CARD,DEV or plughw:Name,DEV
    prefix = "plughw:"
    if rng.random() < 0.6:
        card = str(_card_index(rng))
    else:
        card = _named_card(rng)
    dev = str(_dev_index(rng))
    return prefix + card + "," + dev


def _sysdefault_form(rng: random.Random) -> str:
    # sysdefault or sysdefault:CARD=n/Name
    if rng.random() < 0.5:
        return "sysdefault"
    if rng.random() < 0.6:
        return f"sysdefault:CARD={_card_index(rng)}"
    return f"sysdefault:CARD={_named_card(rng)}"


def _dmix_form(rng: random.Random) -> str:
    # dmix, dmix:CARD=0,DEV=0
    if rng.random() < 0.5:
        return "dmix"
    parts = [f"CARD={_card_index(rng)}"]
    if rng.random() < 0.8:
        parts.append(f"DEV={_dev_index(rng)}")
    return "dmix:" + ",".join(parts)


def _dsnoop_form(rng: random.Random) -> str:
    # dsnoop or dsnoop:CARD=...,DEV=...
    if rng.random() < 0.5:
        return "dsnoop"
    parts = [f"CARD={_card_index(rng)}"]
    if rng.random() < 0.8:
        parts.append(f"DEV={_dev_index(rng)}")
    return "dsnoop:" + ",".join(parts)


def _plug_chain_form(rng: random.Random) -> str:
    # plug:hw:0,0 or plug:dmix or plug:plughw:Name,0
    inner_choices = [
        _hw_form(rng),
        _plughw_form(rng),
        "dmix",
        "dsnoop",
        "default",
    ]
    return "plug:" + _choice(rng, inner_choices)


def _default_form(rng: random.Random) -> str:
    # default or default:CARD=n
    if rng.random() < 0.7:
        return "default"
    return f"default:CARD={_card_index(rng)}"


def _null_form(_: random.Random) -> str:
    return "null"


def _with_params(rng: random.Random, base: str) -> str:
    # Append simple ALSA parameter dictionary to exercise parser paths.
    # Example: hw:0,0 { format S16_LE rate 48000 channels 2 }
    # Keep parameters simple and valid-ish.
    param_keys = [
        ("format", [
            "S16_LE", "S24_LE", "S32_LE", "FLOAT_LE", "S16_BE", "FLOAT_BE"
        ]),
        ("rate", ["44100", "48000", "96000", "22050", "32000"]),
        ("channels", ["1", "2", "4", "6", "8"]),
        ("period_time", ["10000", "20000", "5000"]),
        ("buffer_time", ["40000", "100000", "200000"]),
    ]
    # Pick 1-3 params
    k = rng.randint(1, 3)
    chosen = rng.sample(param_keys, k)
    parts = []
    for key, vals in chosen:
        parts.append(key)
        parts.append(_choice(rng, vals))
    param_str = " { " + " ".join(parts) + " }"
    s = base + param_str
    if len(s) > MAX_LEN:
        # If too long, fall back to base only
        return base
    return s


def _generate_device_string(rng: random.Random) -> str:
    # Choose a base form
    forms = [
        _default_form,
        _sysdefault_form,
        _hw_form,
        _plughw_form,
        _dmix_form,
        _dsnoop_form,
        _plug_chain_form,
        _null_form,
    ]
    base = _choice(rng, forms)(rng)
    # Occasionally add params
    if rng.random() < 0.35:
        base = _with_params(rng, base)
    # Ensure length cap to match stub behavior
    if len(base) > MAX_LEN:
        base = base[:MAX_LEN]
    return base


def _maybe_multiple_candidates(rng: random.Random) -> bytes:
    # The fuzzer infra may read a single FUZZ_PARAM_STR, but sometimes having
    # multiple newline-separated candidates in one blob allows consumers that split
    # by newlines to try different options. Keep total size small.
    count = 1
    p = rng.random()
    if p < 0.15:
        count = 2
    elif p < 0.18:
        count = 3
    items = [_generate_device_string(rng) for _ in range(count)]
    return ("\n".join(items)).encode("utf-8")


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # 70%: single clean device string
    # 30%: multiple newline-separated candidates
    if rng.random() < 0.7:
        s = _generate_device_string(rng)
        return s.encode("utf-8")
    return _maybe_multiple_candidates(rng)
